(167,'services','Services Directory','Services Directory FAQPage','FAQPage','{\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What commercial usage rights do you provide?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"You can use the finished videos in paid ads on Meta, TikTok, YouTube and Google. The exact platforms\\r\\n                and duration are in your project agreement, so read that before signing. [ADD YOUR REAL TERMS]\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How long does production take?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Most projects take about 7 to 12 business days, from brief to final video. A big batch or slow feedback\\r\\n                can add time.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How do you select creators?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"We look at your product, your audience and the platform. Then we shortlist creators whose style and\\r\\n                followers suit it, and who are free on your dates.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do clients approve scripts before filming?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. We send the script and hooks first. Filming starts only after you say yes.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What aspect ratios are delivered?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"9:16, 4:5, 1:1 and 16:9, as MP4 files. Captions can be burned in, and we can send separate SRT subtitle\\r\\n                files too.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How are revisions handled?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Send all your feedback together and we\'ll make the changes. [ADD YOUR REAL REVISION LIMIT, like 2\\r\\n                rounds]\"\n            }\n        }\n    ]\n}','published','2026-11-18 11:38:40','2026-11-18 11:38:40'),
